  BlockFieldManager<FLAG, T, LatSet::d> FlagFM(Geo, VoidFlag);
  FlagFM.forEach(aabb_0_Cavity, [&](FLAG& field, std::size_t id) { field.SetField(id, BulkFlag); });
  FlagFM.template SetupBoundary<LatSet>(aabb_1_Walls, WallFlag);
  FlagFM.forEach(aabb_2_Lid, [&](FLAG& field, std::size_t id) {
    if (util::isFlag(field.get(id), WallFlag)) field.SetField(id, MovingWallFlag);
  });

  // spec-vs-geometry self-check: a flag that painted nothing is a
  // silently non-colliding region, so fail instead of running it.
