  std::size_t count_Bulk = 0;
  std::size_t count_Wall = 0;
  std::size_t count_MovingWall = 0;
  FlagFM.forEach([&](FLAG& field, std::size_t id) {
    const std::uint8_t f = field.get(id);
    if (util::isFlag(f, VoidFlag)) ++count_Void;
    if (util::isFlag(f, BulkFlag)) ++count_Bulk;
    if (util::isFlag(f, WallFlag)) ++count_Wall;
    if (util::isFlag(f, MovingWallFlag)) ++count_MovingWall;
  });
  
  auto globalCount = [](std::size_t local) -> std::size_t {
  #ifdef MPI_ENABLED
    unsigned long long in = static_cast<unsigned long long>(local);
    unsigned long long total = 0;
    MPI_Allreduce(&in, &total, 1, MPI_UNSIGNED_LONG_LONG, MPI_SUM, MPI_COMM_WORLD);
    return static_cast<std::size_t>(total);
  #else
    return local;
  #endif
  };
  count_Void = globalCount(count_Void);
  count_Bulk = globalCount(count_Bulk);
  count_Wall = globalCount(count_Wall);
  count_MovingWall = globalCount(count_MovingWall);
  
  std::cout << "[flags] "
            << "void = " << count_Void << "  "
            << "bulk = " << count_Bulk << "  "
            << "wall = " << count_Wall << "  "
            << "moving_wall = " << count_MovingWall << "  "
            << std::endl;
  if (count_Bulk == 0) { std::cerr << "[flags] flag bulk has no cells\n"; return 1; }
  if (count_Wall == 0) { std::cerr << "[flags] flag wall has no cells\n"; return 1; }
  if (count_MovingWall == 0) { std::cerr << "[flags] flag moving_wall has no cells\n"; return 1; }

  // ------------------ lattice ------------------
  using FIELDS = TypePack<RHO<T>, VELOCITY<T, LatSet::d>, POP<T, LatSet::q>>;
  using CELL = Cell<T, LatSet, FIELDS>;
  ValuePack InitValues(BaseConv.getLatRhoInit(), Vector<T, LatSet::d>{}, T{});
  BlockLatticeManager<T, LatSet, FIELDS> NSLattice(Geo, InitValues, BaseConv);

  // set_velocity actions run here: they write VELOCITY, which
  // only exists after the lattice manager is built.
  Vector<T, LatSet::d> LatU_3_LidVelocity(BaseConv.getLatticeU(Vector<T, LatSet::d>{T(0.1), T(0.0), T(0.0)}));
  NSLattice.getField<VELOCITY<T, LatSet::d>>().forEach(
      aabb_3_LidVelocity, FlagFM, MovingWallFlag,
      [&](auto& field, std::size_t id) { field.SetField(id, LatU_3_LidVelocity); });

  // ------------------ tasks ------------------
  using Task_0_Bulk = tmp::Key_TypePair<BulkFlag, collision::BGK<moment::rhoU<CELL>, equilibrium::SecondOrder<CELL>>>;
  using Task_1_Wall = tmp::Key_TypePair<WallFlag, collision::BounceBack<CELL>>;
  using Task_2_MovingWall = tmp::Key_TypePair<MovingWallFlag, collision::BounceBackMovingWall<CELL>>;
  using RhoUTask_0_Bulk = tmp::Key_TypePair<BulkFlag, moment::rhoU<CELL, true>>;
  
  using TaskCollection = tmp::TupleWrapper<Task_0_Bulk, Task_1_Wall, Task_2_MovingWall>;
  using NSTask = tmp::TaskSelector<TaskCollection, std::uint8_t, CELL>;
  using TaskCollectionRhoU = tmp::TupleWrapper<RhoUTask_0_Bulk>;
  using TaskSelectorRhoU = tmp::TaskSelector<TaskCollectionRhoU, std::uint8_t, CELL>;

  // ------------------ writers ------------------
  vtmo::ScalarWriter RhoWriter("Rho", NSLattice.getField<RHO<T>>());
  vtmo::VectorWriter VelocityWriter("Velocity", NSLattice.getField<VELOCITY<T, LatSet::d>>());
  vtmo::vtmWriter<T, LatSet::d> NSWriter("cavity3d", Geo);
  NSWriter.addWriterSet(RhoWriter, VelocityWriter);

  // ------------------ restart ------------------
