  NSLattice.NormalFullCommunicate();
  NSLattice.ApplyCellDynamics<TaskSelectorRhoU>(FlagFM);
  
  std::array<double, 3> pop_s{0.0, 0.0, 0.0};
  for (auto& bl : NSLattice.getBlockLats()) {
    const std::array<double, 3> s = frelb_diag::PopChecksumHost(bl.getField<POP<T, LatSet::q>>(), bl.getN(), LatSet::q);
    pop_s[0] += s[0];
    pop_s[1] += s[1];
    pop_s[2] = s[2] > pop_s[2] ? s[2] : pop_s[2];
  }
  frelb_diag::PrintChecksum("pop", pop_s);
  
  // RHO uses the same measure and the same all-block-cell order as
  // the pop checksum: the field manager's default forEach.
  double rho_sum = 0.0, rho_sumsq = 0.0, rho_maxabs = 0.0;
  NSLattice.getField<RHO<T>>().forEach([&](auto& field, std::size_t id) {
    const double v = static_cast<double>(field.get(id));
    rho_sum += v;
    rho_sumsq += v * v;
    const double a = v < 0.0 ? -v : v;
    rho_maxabs = a > rho_maxabs ? a : rho_maxabs;
  });
  const std::array<double, 3> rho_s{rho_sum, rho_sumsq, rho_maxabs};
  frelb_diag::PrintChecksum("rho", rho_s);
  
  constexpr double kExpectPop = 1327.451851;
  constexpr double kExpectRho = 5831.917013;
  constexpr double kChecksumTol = 1e-06;
  
  bool ok = std::isfinite(pop_s[0]) &&
          std::isfinite(pop_s[1]) &&
          std::isfinite(pop_s[2]) &&
          std::isfinite(rho_s[0]) &&
          std::isfinite(rho_s[1]) &&
          std::isfinite(rho_s[2]);
  if (std::abs(pop_s[1] - kExpectPop) > kChecksumTol * std::abs(kExpectPop)) ok = false;
